import{_ as e,o as a,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const T=JSON.parse('{"title":"Zero Trust Data Lakehouse","description":"","frontmatter":{"title":"Zero Trust Data Lakehouse","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["分布式存储","Ceph","零信任安全","Lakehouse 架构","数据治理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Zero_Trust_Data_Lakehouse.md","filePath":"posts/2025/Zero_Trust_Data_Lakehouse.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Zero_Trust_Data_Lakehouse.md"};function s(r,l,p,u,n,_){return a(),t("div",null,[...l[0]||(l[0]=[o("<p>会议纪要中提到了Ceph分布式存储在零信任Lakehouse架构中的应用，以下是会议的关键点：</p><ol><li><p><strong>Ceph对象存储的优势</strong>：</p><ul><li>高扩展性与高可用性；</li><li>支持结构化/非结构化数据，如Parquet、多模态嵌入数据；</li><li>企业级特性，包括加密、Kafka/Knative集成、对象日志等。</li></ul></li><li><p><strong>Lakehouse架构挑战</strong>：</p><ul><li>数据治理问题，特别是多引擎访问同一数据集时的权限管理；</li><li>零信任需求，包括防止数据泄露、存储层统一认证；</li><li>性能与扩展性，避免代理成为瓶颈。</li></ul></li><li><p><strong>Polaris Catalog解决方案</strong>：</p><ul><li>Catalog凭证分发，使用临时STS Token，基于最小权限；</li><li>细粒度访问控制，包括表级权限和命名空间隔离。</li></ul></li><li><p><strong>演示环节</strong>：</p><ul><li>Terraform自动化部署，创建S3 Bucket、IAM策略、Polaris Catalog；</li><li>Spark与Trino测试，展示用户权限管理。</li></ul></li><li><p><strong>决策与行动计划</strong>：</p><ul><li>技术方向，推动Ceph RGW与Polaris Catalog深度集成，优化STS Token审计日志；</li><li>发布Ceph Lakehouse红皮书，提供实际用例与部署指南；</li><li>社区合作，增强RGW对分析负载的支持。</li></ul></li><li><p><strong>用户建议</strong>：</p><ul><li>迁移HDFS到Ceph对象存储（通过S3A连接器）；</li><li>使用Polaris Catalog实现跨团队数据共享。</li></ul></li></ol><p>会议强调了Ceph在构建高可用、高扩展性的Lakehouse架构中的关键作用，并讨论了如何通过Polaris Catalog实现零信任安全模型下的数据治理和访问控制。会议还展示了如何使用Terraform自动化部署和测试不同的数据查询引擎，以确保系统的性能和安全性。</p>",3)])])}const h=e(i,[["render",s]]);export{T as __pageData,h as default};
